sig Node { edge: set Node }
fact Dag { no iden & ^edge }
assert NoReturn { all n: Node | n not in n.^edge }
assert Reflexive { iden & (Node -> Node) in *edge }
Safe: check NoReturn for 3 but 0 Int
ReflexiveClosure: check Reflexive for 3 but 0 Int
Chain: run { some a, b, c: Node | a -> b in edge and b -> c in edge } for 3 but 0 Int

sig V { e: set V }
fact Symmetric { e = ~e }
fact Irreflexive { no iden & e }
Triangle: run { some disj a, b, c: V | a -> b + b -> c + c -> a in e } for 4 but 0 Int
assert Connected { all disj a, b: V | a -> b in ^e }
NotConnected: check Connected for 4 but 0 Int
Matching: run { all v: V | one v.e } for 4 but exactly 4 V, 0 Int

sig A {}
sig B { to: set A }
ExactThree: run { all b: B | b.to = A } for 4 but exactly 3 A, exactly 2 B, 0 Int
Empty: run { no A and no B } for 2 but 0 Int
Zero: run { some A } for 0 but 0 Int

sig Node { edge: set Node }
fact NoSelfLoops { no iden & edge }
assert Acyclic { no iden & ^edge }
Cyclic: check Acyclic for 3 but 0 Int
TwoCycle: run { some n: Node | n in n.^edge } for 2 but 0 Int
Dag: run { no iden & ^edge and some edge } for 3 but 0 Int

sig P { q: set P }
assert Contrapositive { (some q => some P) <=> (no P => no q) }
assert BadConverse { (some q => some P) <=> (some P => some q) }
Contra: check Contrapositive for 3 but 0 Int
Converse: check BadConverse for 2 but 0 Int
Iff: run { some q <=> no P } for 2 but 0 Int

sig Pigeon { hole: one Hole }
sig Hole {}
fact Injective { all disj p, q: Pigeon | p.hole != q.hole }
Fit: run { } for 3 but exactly 3 Pigeon, exactly 3 Hole, 0 Int
Overflow: run { } for 3 but exactly 3 Pigeon, exactly 2 Hole, 0 Int
assert Distinct { all disj p, q: Pigeon | p.hole != q.hole }
Holds: check Distinct for 3 but 0 Int

sig Node { next: lone Node }
pred Ring { all n: Node | Node in n.^next }
pred Line { some n: Node | no n.next }
fact { some Node }
RingExists: run Ring for 3 but 0 Int
LineExists: run Line for 3 but 0 Int
assert RingNoEnd { Ring => no n: Node | no n.next }
RingHasNoEnd: check RingNoEnd for 3 but 0 Int

sig S { a: set S, b: set S }
assert UnionCommutes { a + b = b + a }
assert DiffSubset { a - b in a }
assert InterLaw { a & b = a - (a - b) }
assert Wrong { a - b = b - a }
Union: check UnionCommutes for 3 but 0 Int
Diff: check DiffSubset for 3 but 0 Int
Inter: check InterLaw for 3 but 0 Int
Broken: check Wrong for 2 but 0 Int

one sig Root { child: set Leaf }
lone sig Spare {}
some sig Leaf {}
RootOnly: run { no Leaf } for 3 but 0 Int
SpareAbsent: run { no Spare } for 3 but 0 Int
AllChildren: run { Root.child = Leaf } for 3 but 0 Int
